{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Terfenadine, a lipophilic drug with a large aromatic/hydrophobic substituent and extensive CYP3A4 first-pass metabolism, has absolute oral bioavailability <2% in humans; this strongly supports low oral bioavailability for the query's long lipophilic dichlorobenzyl side chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Epanolol, a phenolic beta-amino alcohol with an ether-linked aromatic side chain, has absolute oral bioavailability of about 7% in fasted volunteers, directly demonstrating that this structural class can undergo extensive first-pass elimination and yield low systemic F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Bambuterol, a lipophilic derivative of a beta2 agonist, has oral bioavailability of about 10% in healthy adults, showing that even deliberately lipophilic modifications of beta-agonist scaffolds do not ensure high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Phenylephrine, a phenolic beta-hydroxy amine, has poor oral bioavailability in healthy volunteers despite being potent intravenously, supporting low F for the query's phenolic beta-hydroxy amine core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Hydroxytyrosol, a small phenolic compound, has free oral bioavailability of only about 6.2% in humans, illustrating that phenolic/benzylic alcohol motifs are prone to extensive first-pass conjugation and low systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Salbutamol, which shares the hydroxymethyl-phenol beta-hydroxy amine headgroup, has absolute oral bioavailability of 44% in healthy volunteers; this is the strongest evidence for high F, but its small tert-butyl N-substituent is not representative of the query's long lipophilic dichlorobenzyl-PEG-hexyl chain.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a long-acting beta2 agonist with a lipophilic dichlorobenzyl-PEG-hexyl N-substituent. Although salbutamol shares the polar headgroup and has ~44% F, the preponderance of transferable human data from lipophilic beta-agonist/antagonist analogues (terfenadine <2%, epanolol ~7%, bambuterol ~10%, phenylephrine poor) indicates extensive first-pass metabolism and low oral bioavailability. Therefore predict low (<20%).",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule is present in the supplied records.",
    "Salbutamol's high F is contradictory but its small N-substituent limits transferability to the query's large lipophilic side chain.",
    "No explicit human data on the query's permeability, first-pass metabolism, or transporter involvement are provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

